from lib import *
S = SS('n50')
steps = [
    step("先看行为,因为性能比较只有在行为对等时才有意义。Go 1.27.1 的 ServeMux(GET /users/{id} 这样的模式)与 Gin 的差别:方法不对(POST /users/42)ServeMux 自动返回 405 和 Allow: GET, HEAD,Gin 默认 404;HEAD 请求 ServeMux 把 GET 模式也匹配上(200),Gin 是 404;/users/42/ 多一个斜杠,ServeMux 404,Gin 301 到 /users/42;/dir 对注册的 GET /dir/ ServeMux 是 307、Gin 是 301;/dir/x 命中 ServeMux 的子树模式 /dir/(200),Gin 的 /dir/ 只匹配这一个路径(404);/users//42 ServeMux 307 去掉多余斜杠,Gin 404;通配符的值:ServeMux 的 {path...} 不带开头的斜杠(a/b.txt),Gin 的 *path 带(/a/b.txt)。静态的 /users/new 与参数路由并存两边都支持。", t=tl(S(1)), mark=lidx(S(1), 'POST  /users/42', 'HEAD  /users/42', 'GET   /dir/x', 'GET   /users//42', 'GET   /files/a/b.txt'), done=lidx(S(1), 'GET   /users/42  ', 'GET   /users/new'), kv=KV([['方法不对', 'ServeMux 自动 405;Gin 默认 404'], ['HEAD', 'ServeMux 让 GET 模式也匹配 HEAD;Gin 不会'], ['通配符的值', 'ServeMux 不带开头 /,Gin 带']], ['方法不对'])),
    step("路由数量与命中一条路由的耗时(随机 1024 个请求轮流,空 handler,5 轮中位数,ServeHTTP + 丢弃输出的 writer):静态路由 1 / 100 / 1000 / 10000 条,ServeMux 130 / 145 / 158 / 162 ns,Gin 26 / 52 / 67 / 88 ns;带参数的路由,ServeMux 174 / 188 / 199 / 201 ns(每次 1 次分配),Gin 31 / 59 / 78 / 102 ns(0 次分配)。路由匹配这一步 Gin 比 ServeMux 快 1.6~5.6 倍,两者都随路由数缓慢增长。", t=tl(S(2)), mark=lidx(S(2), '10000 |'), done=lidx(S(2), '[静态路由]', '[带 {id} / :id 的路由]', '      1 |', '    100 |'), b=bars([['ServeMux:静态 1 条', 130, '130 ns'], ['Gin:静态 1 条', 26, '26 ns'], ['ServeMux:静态 1 万条', 162, '162 ns'], ['Gin:静态 1 万条', 88, '88 ns']], 162, mark=[1, 3], done=[0, 2]), kv=KV([['1 条静态路由', 'Gin 26 ns,ServeMux 130 ns'], ['1 万条参数路由', 'Gin 102 ns,ServeMux 201 ns(+1 次分配)'], ['分配', 'Gin 命中路由 0 次,ServeMux 带参数 1 次']], ['1 条静态路由'])),
    step("加上一点真实的工作(同样写一个 {\"id\":\"42\"}):JSON 方式,ServeMux 用 json.Encoder 517 ns / 7 次分配,Gin 的 c.JSON(gin.H) 589 ns / 9 次分配;字符串方式,ServeMux 的 Fprintf 140 ns / 2 次分配,Gin 的 c.String 188 ns / 3 次分配(第二轮 513 / 591 / 139 / 188 ns)。一旦 handler 做了真实工作,路由快几十纳秒就被淹没了——JSON 场景下 Gin 反而慢约 70 ns(gin.H 是 map、Context 封装的额外开销)。", t=tl(S(3)), mark=lidx(S(3), '第 1 轮'), done=lidx(S(3), '第 2 轮'), b=bars([['ServeMux + json.Encoder', 517, '517 ns'], ['Gin c.JSON(gin.H)', 589, '589 ns'], ['ServeMux + Fprintf', 140, '140 ns'], ['Gin c.String', 188, '188 ns']], 589, done=[0, 2], mark=[1, 3]), kv=KV([['只路由', 'Gin 快 1.6~5.6 倍'], ['写 JSON', 'ServeMux 517 ns,Gin 589 ns'], ['结论', '选框架看功能,不是看路由那几十纳秒']], ['结论'])),
]
A = mkartn('n50', 50, 'Gin,http.ServeMux,基准测试,路由性能,Go 1.22,Go,真实验证,动画演示',
    '在 Gin v1.12.0 与 Go 1.27.1 的 http.ServeMux 之间做对等的比较:行为差异(405、HEAD、尾斜杠、通配符值是否带斜杠);路由匹配 Gin 26~102 ns、ServeMux 130~201 ns,Gin 命中 0 次分配;但 handler 写一个小 JSON 时 ServeMux 517 ns、Gin 589 ns,路由的差异被淹没。',
    'Go 1.22 之后标准库的 ServeMux 也支持方法和通配符了,还需要 Gin 吗?这篇不做口号式的“谁更快”,而是先对齐行为差异,再测纯路由匹配的耗时,最后加上 handler 的真实工作,看路由的几十纳秒在整个请求里占多大比重。',
    [('26 vs 130 ns', '1 条静态路由时 Gin 与 ServeMux 的单次路由耗时'), ('88 vs 162 ns', '1 万条静态路由时的耗时'), ('517 vs 589 ns', '含 JSON 序列化时 ServeMux(json.Encoder)与 Gin(c.JSON)的耗时')],
    [('行为不是对等的', '<p>ServeMux 有一些 Gin 默认没有的“自动行为”:方法不匹配返回 405 与 <code>Allow</code>,HEAD 自动匹配 GET 模式,多余斜杠 307 重定向。Gin 则默认 404(需要 <code>HandleMethodNotAllowed</code>)、HEAD 单独注册、尾斜杠 301。通配符的值也不同:ServeMux 的 <code>{path...}</code> 不带开头的斜杠,Gin 的 <code>*path</code> 带。迁移时这些都是需要逐项确认的地方。</p>'),
     ('纯路由匹配', '<p>只测路由匹配(空 handler),Gin 的 radix 树明显更快:1 条静态路由 26 ns 对 130 ns,1 万条带参数的路由 102 ns 对 201 ns;Gin 命中路由 0 次分配,ServeMux 带参数时每次 1 次分配(取参数)。两者随路由数的增长都很缓慢。</p>'),
     ('放到真实请求里', '<p>handler 里一旦做点事,差距就没了:同样写一个小 JSON,ServeMux 配 <code>json.Encoder</code> 517 ns,Gin 的 <code>c.JSON(gin.H)</code> 589 ns,反而慢一点(<code>gin.H</code> 是 map、Context 的封装也有开销)。一个真实服务的单次请求是微秒到毫秒级(数据库、网络),路由那几十纳秒不是选型的理由。选 Gin 的理由应该是中间件、绑定、校验、渲染这些功能,而不是性能。</p>')],
    steps,
    [ENV_N_GIN + '。ServeMux 用 Go 1.27.1 的 http.NewServeMux(带方法与通配符的模式);基准是 testing.Benchmark,5 轮中位数,整个实验跑了两遍,数字相差在 3 ns 以内(正文取最后一遍),输出是丢弃内容的 ResponseWriter;命中的请求是 1024 个随机路径轮流;不含网络与真实 handler 逻辑',
     '没有验证:多核并发下两者的吞吐;注册 1 万条路由的耗时(尝试时程序编译失败,没有重测,所以没有数字);其它路由库(httprouter、chi 等);带中间件链的整体对比;真实网络下的 QPS;ServeMux 在更大路由表(几十万)下的表现'],
    'Gin 与 ServeMux')
